cd /workspace && python3 - <<'PY'
import re,math
p='run/experiments/logs/user/kt-seeds/icepop_w067-s2/main.log'
rows={};cur=None
def get(n):
    for k in rows[u] if False else ():
        pass
keys=['rs_filtered_fraction','logp_abs_diff/avg','entropy/avg','behave_filtered_ratio/avg','rollout/reward']
rows={};cur=None
data={}
for line in open(p,errors='replace'):
    m=re.search(r'Train step (\d+)/\d+ done',line)
    if m: cur=int(m.group(1)); data.setdefault(cur,{}); continue
    if cur is None: continue
    for m in re.finditer(r'([A-Za-z][A-Za-z0-9_/\-]+)\s*│\s*([-\d.eE+]+)\s*│',line):
        n,v=m.group(1),float(m.group(2))
        for k in keys:
            if n.endswith('/'+k): data[cur][k]=v
steps=sorted(data)
def series(k): return [data[s].get(k) for s in steps]
def stats(k):
    xs=[x for x in series(k) if x is not None]
    return min(xs),max(xs),sum(xs)/len(xs)
for k in keys: print(k,'min/max/mean',['%.4g'%x for x in stats(k)])
def corr(a,b):
    xs=[x for x in zip(series(a),series(b)) if None not in x]
    n=len(xs); ma=sum(x for x,_ in xs)/n; mb=sum(y for _,y in xs)/n
    sa=math.sqrt(sum((x-ma)**2 for x,_ in xs)); sb=math.sqrt(sum((y-mb)**2 for _,y in xs))
    return sum((x-ma)*(y-mb) for x,y in xs)/(sa*sb)
print('corr(rs_filtered, logp_abs_diff) =', round(corr('rs_filtered_fraction','logp_abs_diff/avg'),3))
print('corr(rs_filtered, entropy) =', round(corr('rs_filtered_fraction','entropy/avg'),3))
rs=series('rs_filtered_fraction')
print('rs last 10 mean', round(sum(rs[-10:])/10,4), 'first 10 mean', round(sum(rs[:10])/10,4))
print('steps with rs>0.5:', [s for s in steps if data[s].get('rs_filtered_fraction',0)>0.5])
print('entropy>1 count:', sum(1 for s in steps if data[s].get('entropy/avg',0)>1))
PY

